def correctedRetraction (J : D →L[𝕜] E) (R : E →L[𝕜] D)
    (h : ‖1 - R.comp J‖ < 1) : E →L[𝕜] D :=
  ((↑(Units.oneSub (1 - R.comp J) h)⁻¹ : D →L[𝕜] D)).comp R

